O = list(range(len(operations)))

c = [
    operations[o]["cost"]
    for o in O
]

V = [6, 8, 11, 13, 16, 18]

O_v = {
    v: [
        o for o in O
        if v in operations[o]["nodes"]
    ]
    for v in V
}

#print(O_v)
'''
for o in O:
    op = operations[o]
    print(f"{o}\n"
          f"{op["nodes"]}\n"
          f"{op["cost"]}\n")
'''
model = gp.Model("Agatz_TSPD")


# ---------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------

x = model.addVars(
    O,
    vtype=gp.GRB.BINARY,
    name="x"
)


#y = model.addVars(
#    V,
#    vtype=gp.GRB.BINARY,
#    name="y"
#)

# ---------------------------------------------------------
# OBJECTIVE
# ---------------------------------------------------------

model.setObjective(

    gp.quicksum(
        c[o] * x[o]
        for o in O
    ),

    sense=gp.GRB.MINIMIZE
)

model.Params.OutputFlag = 0

# =========================================================
# (14)
#
# Every node must belong to at least one selected operation
# =========================================================

model.addConstrs(

    (
        gp.quicksum(
            x[o]
            for o in O_v[v]
        )
        >= 1

        for v in V
    ),

    name="cover"
)


# =========================================================
# SOLVE
# =========================================================

model.optimize()


# =========================================================
# PRINT SELECTED OPERATIONS
# =========================================================

if model.status == gp.GRB.OPTIMAL:

    print()
    print("==============================")
    print("OPTIMAL SOLUTION")
    print("==============================")
    print()

    print(
        "Total cost:",
        model.objVal
    )

    print()
    for o in O:
        if(x[o].X > 0.5):
            op = operations[o]
            print(f"Operation {o}\n"
                  f"{op["nodes"]}\n"
                  f"{op["cost"]}\n"
                  "==============\n")
            